from comfy_trials import *
master=upload(OUT/'v2-master.png')
def ref(name):return upload(OUT/(name+'.png'))
run('v3b-attack-C','图1是挥剑蓄力的上一帧，图2只提供服饰细节。现在画图1动作的下一关键帧：双手握着同一把剑从头顶劈向右下方，双手已经来到胸口前方，剑刃向右下方伸出。前腿继续承重弯曲，后脚蹬地，腰背明显向右前方压低，头向前探且低头，胸腔转动带动肩膀。保持图1的身体大小、脚的位置、脸、铠甲设计和画风。马尾和披风滞后甩向左。全身完整，剑刃完整，灰色背景。不是站立姿势，不是刺剑，是从上往下劈。只有两臂两手一把剑。',ref('v3b-attack-A'),master,size=(1024,1024))
run('v3b-attack-D','图1是向下劈剑的上一帧，图2只提供角色设计。画动作结束的下一帧：双手持同一把剑继续落到前腿膝盖旁，剑刃斜向右下方，剑尖靠近地面但完整在画布内。前膝更深弯曲，腰弯下，胸腔和头向前下方跟随收势，后腿伸直，马尾及披风开始回落。保持图1身体大小、脚的位置和服装，脸仍是同一个角色。灰色背景，单个人物，精美二维插画。',ref('v3b-attack-C'),master,size=(1024,1024))
run('v3b-attack-AC','图1是较早的举剑蓄力关键帧，图2是较晚的下劈关键帧，图3只是角色设计参考。生成图1和图2之间的一张过渡帧。双手握一把剑刚刚从头顶向前下方运动，剑尚在头的右上方。躯干、头和骨盆的位置应在图1和图2之间，身体正在前倾，头随之下降。不要把两帧人物或肢体叠加，只画一个人物两只手一把剑。保持服装、人物尺寸与脚下地面位置。精美二维插画，完整全身，灰色背景。',ref('v3b-attack-A'),ref('v3b-attack-C'),size=(1024,1024),end=master)
run('v3b-attack-CD','图1是较早的下劈关键帧，图2是较晚的收势关键帧，图3只是角色设计。生成两关键帧中间的一张过渡帧：双手共同握一把剑在腰部前下方，剑往右下方运动；头、躯干和骨盆一起向前下方运动到中间位置。保持脚的位置与人物比例，只画两条手臂两条腿一把剑，不要叠加肢体。保持服装一致、完整全身、灰色背景和精美画风。',ref('v3b-attack-C'),ref('v3b-attack-D'),size=(1024,1024),end=master)
